// Generated by agent — 2026-06-06
// Generates docs/altstore-source.json from packages/app/app.json.
// Run by CI: bun .github/scripts/generate-altstore-source.js
// Reads VERSION, BUILD_DATE, IPA_SIZE from env.

const { expo } = require("../../packages/app/app.json");

// Extract permission strings from the plugins array
let cameraPerm = "Allow this app to access your camera.";
let calendarPerm = "Allow this app to add events to your calendar.";
for (const plugin of expo.plugins ?? []) {
  if (Array.isArray(plugin) && plugin.length > 1) {
    const [name, config] = plugin;
    if (name === "expo-camera" && config.cameraPermission)
      cameraPerm = config.cameraPermission;
    if (name === "expo-calendar" && config.calendarPermission)
      calendarPerm = config.calendarPermission;
  }
}

// Convert local icon path (./assets/...) to GitHub raw content URL
const iconRel = (expo.icon ?? "./assets/images/icon.png").replace(/^\.\//, "");
const iconUrl = `https://raw.githubusercontent.com/slashtechno/smartpage/main/packages/app/${iconRel}`;

const downloadUrl =
  "https://github.com/slashtechno/smartpage/releases/download/rolling/smartpage.ipa";

const source = {
  name: expo.name.charAt(0).toUpperCase() + expo.name.slice(1),
  apps: [
    {
      name: expo.name,
      bundleIdentifier: expo.ios.bundleIdentifier,
      developerName: "slashtechno",
      localizedDescription:
        "Capture real-world event information with your camera and add them to your calendar.",
      iconURL: iconUrl,
      downloadURL: downloadUrl,
      versions: [
        {
          version: process.env.VERSION,
          date: process.env.BUILD_DATE,
          downloadURL: downloadUrl,
          size: parseInt(process.env.IPA_SIZE, 10),
        },
      ],
      appPermissions: {
        entitlements: [],
        privacy: {
          NSCameraUsageDescription: cameraPerm,
          NSCalendarsUsageDescription: calendarPerm,
        },
      },
    },
  ],
  news: [],
};

require("fs").writeFileSync(
  "/tmp/altstore-source.json",
  JSON.stringify(source, null, 2) + "\n"
);
